#!/usr/bin/env node
/**
 * Optional one-off cleanup of demo records.
 *
 * Usage: node scripts/purge-demo.mjs --yes
 *
 * Deletes ONLY records generated by the demo seed:
 *  - demo bookings (tracking codes starting with TRK-ATL)
 *  - their generated journal entries + the sample ("seed-*") entries
 *  - demo contact messages and testimonials
 *  - demo special days / their derived daily prices
 *
 * It NEVER deletes admins, settings, accounts, rooms, facilities or gallery items.
 * Always create a backup (pg_dump) before running.
 */
import "dotenv/config";
import { Pool } from "pg";

if (!process.argv.includes("--yes")) {
  console.error("Refusing to run without --yes. Create a backup first: pg_dump \"$DATABASE_URL\" > backup.sql");
  process.exit(1);
}
if (!process.env.DATABASE_URL) {
  console.error("DATABASE_URL is required");
  process.exit(1);
}

const pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 1 });
const DEMO_MESSAGES = ["آرزو نیک‌نام", "کامران اسدی", "پریسا قربانی", "مجتبی راد", "سحر امانی", "فرزاد بیات"];
const DEMO_TESTIMONIALS = ["مهدی رستگار", "سارا موسوی", "امیر کریمی", "فاطمه احمدی", "حسین نوری", "نگار صادقی"];
const DEMO_DAYS = ["تعطیلات پایان هفته طولانی", "تعطیلات رسمی", "آغاز فصل پیک گردشگری"];

try {
  await pool.query("BEGIN");

  const bookings = await pool.query("select id from bookings where tracking_code like 'TRK-ATL%'");
  const bookingIds = bookings.rows.map((row) => row.id);

  if (bookingIds.length > 0) {
    await pool.query("delete from journal_entries where reference = any($1)", [
      bookingIds.map((id) => `booking-${id}`),
    ]);
    await pool.query("delete from bookings where id = any($1)", [bookingIds]);
  }
  await pool.query("delete from journal_entries where reference like 'seed-%'");
  await pool.query("delete from messages where name = any($1)", [DEMO_MESSAGES]);
  await pool.query("delete from testimonials where guest_name = any($1)", [DEMO_TESTIMONIALS]);
  await pool.query("delete from room_daily_prices where note = any($1)", [DEMO_DAYS]);
  await pool.query("delete from special_days where title = any($1)", [DEMO_DAYS]);

  await pool.query("COMMIT");
  console.log(`[purge] done. removed ${bookingIds.length} demo booking(s), demo messages, testimonials and demo accounting/pricing rows.`);
} catch (error) {
  await pool.query("ROLLBACK").catch(() => undefined);
  console.error("[purge] failed:", error.message);
  process.exitCode = 1;
} finally {
  await pool.end();
}
